@@ -469,9 +537,12 @@ CalAlarmService.prototype = {
   },

   addAlarmsForItem(aItem) {
-    if ((aItem.isTodo() && aItem.isCompleted) || IgnoredAlarmsStore.has(aItem)) {
-      // If this is a task and it is completed or the id is in the ignored list,
